create or replace function is_privacy_safe_usage_event(event_name text,properties jsonb) returns boolean language sql immutable as $$select case event_name when 'signed_in' then properties ? 'method' and properties->>'method' in('password','magic_link','sso') and properties-'{method}'='{}'::jsonb when 'funding_assessment_generated' then jsonb_typeof(properties->'durationMs')='number' and jsonb_typeof(properties->'sourceCount')='number' and properties-'{durationMs,sourceCount}'='{}'::jsonb when 'application_answer_approved' then jsonb_typeof(properties->'revisionCount')='number' and properties-'{revisionCount}'='{}'::jsonb when 'report_generated' then jsonb_typeof(properties->'sectionCount')='number' and properties-'{sectionCount}'='{}'::jsonb when 'team_member_invited' then properties->>'role' in('owner','administrator','funding_lead','programme_lead','finance_contributor','trustee_reviewer','contributor') and properties-'{role}'='{}'::jsonb when 'evidence_added' then properties->>'evidenceType' in('document','metric','financial','policy') and properties-'{evidenceType}'='{}'::jsonb else false end$$;
create table privacy_safe_usage_events(id uuid primary key default gen_random_uuid(),customer_account_id uuid not null references customer_accounts(id) on delete cascade,event_name text not null,properties jsonb not null,event_key text not null unique,occurred_at timestamptz not null,received_at timestamptz not null default now(),check(is_privacy_safe_usage_event(event_name,properties)));
create index idx_usage_customer_time on privacy_safe_usage_events(customer_account_id,occurred_at desc);
create table customer_feedback(id uuid primary key default gen_random_uuid(),customer_account_id uuid not null references customer_accounts(id) on delete cascade,category text not null check(category in('product','support','onboarding','outcome','other')),sentiment text not null check(sentiment in('positive','neutral','negative')),summary text not null check(length(summary) between 1 and 500),status text not null check(status in('new','reviewing','planned','resolved','closed')),submitted_at timestamptz not null,created_at timestamptz not null default now());
alter table privacy_safe_usage_events enable row level security;alter table customer_feedback enable row level security;
grant select,insert on privacy_safe_usage_events to authenticated;grant select,insert,update on customer_feedback to authenticated;
create policy usage_events_select on privacy_safe_usage_events for select using(is_active_internal_user());create policy usage_events_insert on privacy_safe_usage_events for insert with check(internal_has_role(array['super_admin','operations','customer_success','product']::internal_role[]));
create policy customer_feedback_select on customer_feedback for select using(is_active_internal_user());create policy customer_feedback_write on customer_feedback for all using(internal_has_role(array['super_admin','operations','customer_success','support','product']::internal_role[])) with check(internal_has_role(array['super_admin','operations','customer_success','support','product']::internal_role[]));
create view customer_usage_aggregates with(security_invoker=true) as select customer_account_id,event_name,count(*)::bigint as event_count,min(occurred_at) as first_occurred_at,max(occurred_at) as last_occurred_at from privacy_safe_usage_events group by customer_account_id,event_name;
grant select on customer_usage_aggregates to authenticated;
revoke all on function is_privacy_safe_usage_event(text,jsonb) from public;grant execute on function is_privacy_safe_usage_event(text,jsonb) to authenticated;
